 "content": "from collections import Counter


def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    bg = Counter(v for row in g for v in row).most_common(1)[0][0]
    runs = []
    for side, col in (("L", 0), ("R", w - 1)):
        r = 0
        while r < h:
            if g[r][col] == bg:
                r += 1
                continue
            start, color = r, g[r][col]
            while r + 1 < h and g[r + 1][col] == color:
                r += 1
            runs.append((side, start, r, color))
            r += 1
    pairs = [(a, b) for a in runs for b in runs
             if a[0] == "L" and b[0] == "R"
             and a[2] - a[1] == b[2] - b[1] and a[3] == b[3]]
    if not pairs:
        return g
    left, right = pairs[0]
    original = [row[:] for row in g]
    for panel, other in ((left, right), (right, left)):
        side, start, end, border = panel
        other_side, other_start, _, _ = other
        for r in range(start, end + 1):
            marks = [(c, original[r][c]) for c in range(1, w - 1)
                     if original[r][c] != bg and original[r][c] != border]
            for c, color in marks:
                # Each marker draws toward its panel's border, then becomes a 4.
                if side == "L":
                    for x in range(1, c):
                        g[r][x] = color
                else:
                    for x in range(c + 1, w - 1):
                        g[r][x] = color
                g[r][c] = 4
                # Project the marker row across the paired panel's full interior.
                paired_row = other_start + (r - start)
                lo = 1 if other_side == "L" else 0
                hi = w - 1 if other_side == "L" else w - 2
                for x in range(lo, hi + 1):
                    g[paired_row][x] = color
    return g
